{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.capsule_overview_dashboard AS WITH capsule_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU_GROUP, TRIM(COLLECTION) AS CAPSULE FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL AND LOWER(TRIM(COLLECTION)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\' ) ), capsule_launch AS ( SELECT * FROM VALUES (\'Street FC\', \'2026-06-23\'::DATE), (\'Street FC Plus\', \'2026-06-23\'::DATE), (\'Botanical Theme\', \'2026-07-11\'::DATE), (\'Embroided Shirts\', \'2026-07-16\'::DATE), (\'Golf Polo Theme\', \'2026-07-27\'::DATE), (\'Photo Print\', \'2026-08-06\'::DATE), (\'Try Less Denim\', \'2026-08-14\'::DATE), (\'Printed Shirts\', \'2026-09-04\'::DATE) AS t(CAPSULE, LAUNCH_DATE) ), sales_base AS ( SELECT c.CAPSULE, UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, TO_DATE(h.DATE) AS SALES_DATE, CASE WHEN h.CHANNEL LIKE \'SNITCH - COCO%\' THEN \'Offline\' WHEN h.CHANNEL LIKE \'SNITCH - FOCO%\' THEN \'Offline\' WHEN h.CHANNEL LIKE \'SNITCH - COFO%\' THEN \'Offline\' WHEN UPPER(h.CHANNEL) IN ( \'MYNTRA\', \'AJIO\', \'AMAZON\', \'FLIPKART\', \'NYKAA\', \'TATACLIQ\', \'TATA CLIQ\' ) THEN \'Online\' WHEN LOWER(h.CHANNEL) IN (\'web\', \'web2\') THEN \'Online\' WHEN LOWER(h.CHANNEL) LIKE \'app%\' THEN \'Online\' ELSE \'Others\' END AS CHANNEL_TYPE, COALESCE(h.GROSS_QUANTITY, 0) AS UNITS_SOLD, COALESCE(h.GROSS_SALES, 0) AS GROSS_SALES, COALESCE(h.DISCOUNT_AMOUNT, 0) AS DISCOUNT FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN capsule_skus c ON UPPER(TRIM(h.SKU_GROUP)) = c.SKU_GROUP ), first_sale AS ( SELECT CAPSULE, MIN(SALES_DATE) AS FIRST_SALE_DATE FROM sales_base WHERE UNITS_SOLD > 0 GROUP BY CAPSULE ), sales_from_first_sale AS ( SELECT sb.CAPSULE, sb.CHANNEL_TYPE, SUM(sb.UNITS_SOLD) AS FIRST_SALE_TO_DATE_QTY FROM sales_base sb INNER JOIN first_sale fs ON sb.CAPSULE = fs.CAPSULE WHERE sb.SALES_DATE >= fs.FIRST_SALE_DATE AND sb.SALES_DATE < CURRENT_DATE() GROUP BY sb.CAPSULE, sb.CHANNEL_TYPE ), sales_from_first_sale_overall AS ( SELECT sb.CAPSULE, SUM(sb.UNITS_SOLD) AS FIRST_SALE_TO_DATE_QTY FROM sales_base sb INNER JOIN first_sale fs ON sb.CAPSULE = fs.CAPSULE WHERE sb.SALES_DATE >= fs.FIRST_SALE_DATE AND sb.SALES_DATE < CURRENT_DATE() GROUP BY sb.CAPSULE ), sales AS ( SELECT CAPSULE, CHANNEL_TYPE, SUM(UNITS_SOLD) AS UNITS_SOLD, SUM(GROSS_SALES) AS GROSS_SALES, SUM(DISCOUNT) AS DISCOUNT FROM sales_base GROUP BY CAPSULE, CHANNEL_TYPE ), sales_overall AS ( SELECT CAPSULE, \'Overall\' AS CHANNEL_TYPE, SUM(UNITS_SOLD) AS UNITS_SOLD, SUM(GROSS_SALES) AS GROSS_SALES, SUM(DISCOUNT) AS DISCOUNT FROM sales_base GROUP BY CAPSULE ), last_30_sales AS ( SELECT CAPSULE, CHANNEL_TYPE, SUM(UNITS_SOLD) AS LAST_30_QTY FROM sales_base WHERE SALES_DATE >= CURRENT_DATE() - 30 AND SALES_DATE < CURRENT_DATE() GROUP BY CAPSULE, CHANNEL_TYPE ), last_30_overall AS ( SELECT CAPSULE, SUM(UNITS_SOLD) AS LAST_30_QTY FROM sales_base WHERE SALES_DATE >= CURRENT_DATE() - 30 AND SALES_DATE < CURRENT_DATE() GROUP BY CAPSULE ), sales_since_launch AS ( SELECT sb.CAPSULE, sb.CHANNEL_TYPE, SUM(sb.UNITS_SOLD) AS LAUNCH_TO_DATE_QTY FROM sales_base sb INNER JOIN capsule_launch cl ON LOWER(TRIM(sb.CAPSULE)) = LOWER(TRIM(cl.CAPSULE)) WHERE sb.SALES_DATE >= cl.LAUNCH_DATE AND sb.SALES_DATE < CURRENT_DATE() GROUP BY sb.CAPSULE, sb.CHANNEL_TYPE ), sales_since_launch_overall AS ( SELECT sb.CAPSULE, SUM(sb.UNITS_SOLD) AS LAUNCH_TO_DATE_QTY FROM sales_base sb INNER JOIN capsule_launch cl ON LOWER(TRIM(sb.CAPSULE)) = LOWER(TRIM(cl.CAPSULE)) WHERE sb.SALES_DATE >= cl.LAUNCH_DATE AND sb.SALES_DATE < CURRENT_DATE() GROUP BY sb.CAPSULE ), inventory AS ( SELECT c.CAPSULE, SUM(COALESCE(i.QTY_AVAILABLE, 0)) AS WH_INVENTORY, SUM(COALESCE(i.QTY_OFFLINE_AVAILABLE, 0)) AS STORE_INVENTORY FROM snitch_db.maplemonk.cogs_daily_snapshot i INNER JOIN capsule_skus c ON UPPER(TRIM(i.SKU_GROUP)) = c.SKU_GROUP WHERE i.DATE = ( SELECT MAX(DATE) FROM snitch_db.maplemonk.cogs_daily_snapshot ) GROUP BY c.CAPSULE ), inwards AS ( SELECT c.CAPSULE, SUM(COALESCE(p.INWARD_QTY, 0)) AS INWARD_QTY FROM capsule_skus c LEFT JOIN ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX( \'-\', REVERSE(\"Item Type skuCode\") ) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_GROUP, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS INWARD_QTY FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1 ) p ON UPPER(TRIM(c.SKU_GROUP)) = p.SKU_GROUP GROUP BY c.CAPSULE ), mrp AS ( SELECT c.CAPSULE, MAX(m.MRP) AS MRP FROM capsule_skus c LEFT JOIN ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), POSITION( \'-\' IN REVERSE(\"Item SkuCode\") ) + 1 ) ) ) ) AS SKU_GROUP, MAX(MRP) AS MRP FROM snitch_db.maplemonk.snitch_final_inventory_wh2 GROUP BY 1 ) m ON UPPER(TRIM(c.SKU_GROUP)) = m.SKU_GROUP GROUP BY c.CAPSULE ), channel_data AS ( SELECT * FROM sales_overall UNION ALL SELECT CAPSULE, CHANNEL_TYPE, UNITS_SOLD, GROSS_SALES, DISCOUNT FROM sales WHERE CHANNEL_TYPE IN (\'Online\', \'Offline\') ), common AS ( SELECT cd.CAPSULE, cd.CHANNEL_TYPE, cl.LAUNCH_DATE, fs.FIRST_SALE_DATE, DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) AS DAYS_SINCE_LAUNCH, cd.UNITS_SOLD, cd.GROSS_SALES, cd.DISCOUNT, CASE WHEN cd.CHANNEL_TYPE = \'Overall\' THEN COALESCE(fsso.FIRST_SALE_TO_DATE_QTY, 0) ELSE COALESCE(fss.FIRST_SALE_TO_DATE_QTY, 0) END AS FIRST_SALE_TO_DATE_QTY, CASE WHEN cd.CHANNEL_TYPE = \'Overall\' THEN COALESCE(l30o.LAST_30_QTY, 0) ELSE COALESCE(l30.LAST_30_QTY, 0) END AS LAST_30_QTY, CASE WHEN cd.CHANNEL_TYPE = \'Overall\' THEN COALESCE(sslo.LAUNCH_TO_DATE_QTY, 0) ELSE COALESCE(ssl.LAUNCH_TO_DATE_QTY, 0) END AS LAUNCH_TO_DATE_QTY, COALESCE(i.WH_INVENTORY, 0) AS WH_INVENTORY, COALESCE(i.STORE_INVENTORY, 0) AS STORE_INVENTORY, COALESCE(i.WH_INVENTORY, 0) + COALESCE(i.STORE_INVENTORY, 0) AS INVENTORY_QTY, COALESCE(w.INWARD_QTY, 0) AS INWARD_QTY, COALESCE(m.MRP, 0) AS MRP, COALESCE(m.MRP, 0) * COALESCE(w.INWARD_QTY, 0) AS OPENING_GMV, COALESCE(m.MRP, 0) * ( COALESCE(i.WH_INVENTORY, 0) + COALESCE(i.STORE_INVENTORY, 0) ) AS INVENTORY_GMV, COALESCE(m.MRP, 0) * COALESCE(cd.UNITS_SOLD, 0) AS SOLD_GMV FROM channel_data cd LEFT JOIN capsule_launch cl ON LOWER(TRIM(cd.CAPSULE)) = LOWER(TRIM(cl.CAPSULE)) LEFT JOIN first_sale fs ON cd.CAPSULE = fs.CAPSULE LEFT JOIN sales_from_first_sale fss ON cd.CAPSULE = fss.CAPSULE AND cd.CHANNEL_TYPE = fss.CHANNEL_TYPE LEFT JOIN sales_from_first_sale_overall fsso ON cd.CAPSULE = fsso.CAPSULE LEFT JOIN last_30_sales l30 ON cd.CAPSULE = l30.CAPSULE AND cd.CHANNEL_TYPE = l30.CHANNEL_TYPE LEFT JOIN last_30_overall l30o ON cd.CAPSULE = l30o.CAPSULE LEFT JOIN sales_since_launch ssl ON cd.CAPSULE = ssl.CAPSULE AND cd.CHANNEL_TYPE = ssl.CHANNEL_TYPE LEFT JOIN sales_since_launch_overall sslo ON cd.CAPSULE = sslo.CAPSULE LEFT JOIN inventory i ON cd.CAPSULE = i.CAPSULE LEFT JOIN inwards w ON cd.CAPSULE = w.CAPSULE LEFT JOIN mrp m ON cd.CAPSULE = m.CAPSULE ) SELECT CAPSULE, CHANNEL_TYPE, LAUNCH_DATE, FIRST_SALE_DATE, DAYS_SINCE_LAUNCH, UNITS_SOLD, GROSS_SALES, DISCOUNT, ROUND( FIRST_SALE_TO_DATE_QTY * 100.0 / NULLIF(INWARD_QTY, 0), 2 ) AS PCT_SOLD, ROUND( LAUNCH_TO_DATE_QTY * 100.0 / NULLIF(INWARD_QTY, 0), 2 ) AS STR, WH_INVENTORY, STORE_INVENTORY, INVENTORY_QTY, ROUND( INVENTORY_QTY * 100.0 / NULLIF(INWARD_QTY, 0), 2 ) AS INVENTORY_LEFT_PCT, INWARD_QTY, OPENING_GMV, INVENTORY_GMV, SOLD_GMV, ROUND( CASE WHEN DAYS_SINCE_LAUNCH < 30 THEN LAUNCH_TO_DATE_QTY * 100.0 / NULLIF(INWARD_QTY, 0) ELSE LAST_30_QTY * 100.0 / NULLIF(INWARD_QTY, 0) END, 2 ) AS STR_30D, ROUND( CASE WHEN DAYS_SINCE_LAUNCH = 0 THEN NULL WHEN DAYS_SINCE_LAUNCH < 30 THEN LEAST( ( LAUNCH_TO_DATE_QTY * 30.0 / DAYS_SINCE_LAUNCH ) * 100.0 / NULLIF(INWARD_QTY, 0), 100 ) ELSE LAST_30_QTY * 100.0 / NULLIF(INWARD_QTY, 0) END, 2 ) AS NORMALIZED_30_STR FROM common ORDER BY CAPSULE, CASE WHEN CHANNEL_TYPE = \'Overall\' THEN 1 WHEN CHANNEL_TYPE = \'Online\' THEN 2 WHEN CHANNEL_TYPE = \'Offline\' THEN 3 ELSE 4 END;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            